# A corner pattern is:
#   frame color at (r, c_left) and (r, c_right) on the same row
#   frame color at (corner_r, c_left) and (corner_r, c_right) on another row
#   with vertical frame colors connecting the corners

def detect_frames_simple(grid):
    """Simple frame detection."""
    rows, cols = len(grid), len(grid[0])
    frames = []

    # Find all unique colors that could be frame colors
    colors = set(grid[r][c] for r in range(rows) for c in range(cols) if grid[r][c] != 6)

    for color in colors:
        # Find all rows where this color appears
        rows_with_color = set()
        col_ranges = {}  # row -> list of (start_col, end_col)

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color:
                    rows_with_color.add(r)

        # For each row with this color, find continuous segments
        for r in rows_with_color:
            segments = []
            start = None
            for c in range(cols):
                if grid[r][c] == color:
                    if start is None:
                        start = c
                elif start is not None:
                    segments.append((start, c-1))
                    start = None
            if start is not None:
                segments.append((start, cols-1))

            # Keep only "reasonable" segments (at least 3 cells - corners + at least 1 border)
            col_ranges[r] = [s for s in segments if s[1] - s[0] >= 2]

        # Now look for frame structures:
        # A frame has at least one "segment" on its top and bottom rows,
        # with corner cells directly above/below each other
        for top_row in col_ranges:
            for top_seg in col_ranges[top_row]:
                top_left, top_right = top_seg

                for bot_row in rows_with_color:
                    for bot_seg in col_ranges[bot_row]:
                        bot_left, bot_right = bot_seg

                        # Check if columns match
                        if set([top_left, top_right]) != set([bot_left, bot_right]):
                            continue

                        frame_height = bot_row - top_row
                        if frame_height < 3:
                            continue

                        # Check if vertical edges are connected
                        vertical_ok = True
                        for r in range(top_row + 1, bot_row):
                            if r not in col_ranges:
                                vertical_ok = False
                                break
                            if not any(abs(seg[0] - top_left) <= 1 and abs(seg[1] - top_left) <= 1 
                                    for seg in col_ranges[r]) or \
                               not any(abs(seg[0] - top_right) <= 1 and abs(seg[1] - top_right) <= 1 
                                    for seg in col_ranges[r]):
                                vertical_ok = False
                                break

                        if vertical_ok:
                            frames.append((top_row, bot_row, top_left, top_right, color))

    return frames

